USE `booking_db`;
CREATE TABLE `booking` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `booking_no` VARCHAR(32) NOT NULL COMMENT '业务单号，对外展示', `user_id` BIGINT UNSIGNED NOT NULL COMMENT '预约人', `resource_id` BIGINT UNSIGNED NOT NULL COMMENT '资源', `start_time` DATETIME NOT NULL COMMENT '开始时间', `end_time` DATETIME NOT NULL COMMENT '结束时间', `purpose` VARCHAR(500) DEFAULT NULL COMMENT '用途说明', `attendee_count` INT DEFAULT NULL COMMENT '预计参与人数', `status` VARCHAR(20) NOT NULL COMMENT '状态机，见下方说明', `checkin_time` DATETIME DEFAULT NULL COMMENT '实际签到时间', `cancel_time` DATETIME DEFAULT NULL COMMENT '取消时间', `cancel_reason` VARCHAR(200) DEFAULT NULL COMMENT '取消原因', `deleted` TINYINT NOT NULL DEFAULT 0, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY `uk_booking_no` (`booking_no`), KEY `idx_user_status` (`user_id`,`status`), KEY `idx_resource_start` (`resource_id`,`start_time`), KEY `idx_status_start` (`status`,`start_time`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='预约主表';
CREATE TABLE `booking_slot` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `resource_id` BIGINT UNSIGNED NOT NULL COMMENT '资源 ID', `slot_time` DATETIME NOT NULL COMMENT '时间片起点，30 分钟粒度对齐', `booking_id` BIGINT UNSIGNED NOT NULL COMMENT '归属的预约 ID', `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY `uk_resource_slot` (`resource_id`,`slot_time`), KEY `idx_booking` (`booking_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='时段占用表——并发控制的核心，唯一索引保证同一资源同一时间片只能被占用一次';
